import { useCallback, useEffect, useRef } from 'react';

// ─── Sun position math (no external dependency) ───────────────────────────────

function rad(deg: number) { return deg * Math.PI / 180; }
function deg(r: number)   { return r * 180 / Math.PI; }

interface SunPos { ra: number; dec: number; gmst: number; }

function sunPosition(date: Date): SunPos {
  const jd = date.getTime() / 86400000 + 2440587.5;
  const n  = jd - 2451545.0;

  // Ecliptic longitude
  const L      = rad((280.460 + 0.9856474 * n) % 360);
  const g      = rad((357.528 + 0.9856003 * n) % 360);
  const lambda = L + rad(1.915 * Math.sin(g) + 0.020 * Math.sin(2 * g));

  // Equatorial coordinates
  const epsilon = rad(23.439 - 0.0000004 * n);
  const ra  = Math.atan2(Math.cos(epsilon) * Math.sin(lambda), Math.cos(lambda));
  const dec = Math.asin(Math.sin(epsilon) * Math.sin(lambda));

  // Greenwich Mean Sidereal Time
  const gmst = rad((280.46061837 + 360.98564736629 * (jd - 2451545)) % 360);

  return { ra, dec, gmst };
}

/** Latitude of the terminator at a given longitude (radians). */
function terminatorLat(sun: SunPos, lngRad: number): number {
  const ha = sun.gmst + lngRad - sun.ra;
  return Math.atan(-Math.cos(ha) / Math.tan(sun.dec));
}

/** Build the night-side polygon as a flat [[lat,lng],...] array. */
function buildNightPolygon(date: Date): [number, number][] {
  const sun    = sunPosition(date);
  const points: [number, number][] = [];

  for (let lng = -180; lng <= 180; lng++) {
    const latRad = terminatorLat(sun, rad(lng));
    points.push([deg(latRad), lng]);
  }

  // Close the polygon over the appropriate pole so the night hemisphere is filled
  const pole: number = sun.dec > 0 ? -90 : 90;
  points.push([pole, 180]);
  points.push([pole, -180]);

  return points;
}

// ─── Component ────────────────────────────────────────────────────────────────

interface TerminatorLayerProps {
  map:     import('leaflet').Map | null;
  enabled: boolean;
}

export function TerminatorLayer({ map, enabled }: TerminatorLayerProps) {
  const polyRef  = useRef<import('leaflet').Polygon | null>(null);
  const timerRef = useRef<ReturnType<typeof setInterval>>();

  const clearAll = useCallback(() => {
    clearInterval(timerRef.current);
    polyRef.current?.remove();
    polyRef.current = null;
  }, []);

  const update = useCallback(() => {
    if (!map || !enabled) return;
    const pts = buildNightPolygon(new Date());
    if (polyRef.current) {
      polyRef.current.setLatLngs(pts);
    } else {
      polyRef.current = window.L.polygon(pts, {
        color:       'transparent',
        fillColor:   '#000',
        fillOpacity: 0.3,
        interactive: false,
      }).addTo(map);
    }
  }, [map, enabled]);

  useEffect(() => {
    if (!map || !enabled) { clearAll(); return; }

    update();
    timerRef.current = setInterval(update, 30_000);
    return clearAll;
  }, [map, enabled, update, clearAll]);

  return null;
}
